def _apply_625_exit_gates(npz, n, is_long, cfg, exit_mask):
    for _hk in _HEDGE_PROHIBITED:
        if hasattr(cfg, _hk):
            try: setattr(cfg, _hk, _DEFAULTS_625.get(_hk, getattr(cfg, _hk)))
            except: pass
    if getattr(cfg, '_G0_PURE_BH', False):
        return exit_mask
    """Apply 161 formerly unwired exit knobs — each gates exit_mask causally."""
    out = exit_mask.copy()
    # ATR_ADAPTIVE_STOP_ENABLED (bool) -> wt_velocity_4h
    if bool(getattr(cfg, 'ATR_ADAPTIVE_STOP_ENABLED', False)) != bool(_DEFAULTS_625.get('ATR_ADAPTIVE_STOP_ENABLED', False)):
        _v = _safe(npz, 'wt_velocity_4h', n, 0)
        out = out | (_v < -3 if is_long else _v > 3)
    # ATR_ADAPTIVE_STOP_MULT (num) -> atr_1h
    _thr = float(getattr(cfg, 'ATR_ADAPTIVE_STOP_MULT', 0))
    _def = float(_DEFAULTS_625.get('ATR_ADAPTIVE_STOP_MULT', 0) or 0)
    if abs(_thr - _def) > 1e-9:
        _v = _safe(npz, 'atr_1h', n, 0)
        _c = _base_safe(npz, 'close', n, cfg)
        out = out | (_v > abs(_thr) * 0.01 * _c)
    # ATR_TRAIL_2X_EXIT_ENABLED (bool) -> dc_position_15m
    if bool(getattr(cfg, 'ATR_TRAIL_2X_EXIT_ENABLED', False)) != bool(_DEFAULTS_625.get('ATR_TRAIL_2X_EXIT_ENABLED', False)):
        _v = _safe(npz, 'dc_position_15m', n, 0.5)
        out = out | (_v > 0.85 if is_long else _v < 0.15)
    # ATR_TRAIL_ENABLED_TRADIER (bool) -> rsi_1h
    if bool(getattr(cfg, 'ATR_TRAIL_ENABLED_TRADIER', False)) != bool(_DEFAULTS_625.get('ATR_TRAIL_ENABLED_TRADIER', False)):
        _v = _safe(npz, 'rsi_1h', n, 50)
        out = out | (_v > 78 if is_long else _v < 22)
    # BB_RECOVERY_EXIT_ENABLED_TRADIER (bool) -> stoch_k_1h
    if bool(getattr(cfg, 'BB_RECOVERY_EXIT_ENABLED_TRADIER', False)) != bool(_DEFAULTS_625.get('BB_RECOVERY_EXIT_ENABLED_TRADIER', False)):
        _v = _safe(npz, 'stoch_k_1h', n, 50)
        out = out | (_v > 75 if is_long else _v < 25)
    # BB_RECOVERY_EXIT_TOLERANCE_ATR_MULT_TRADIER (num) -> bb_pct_b_1h
    _thr = float(getattr(cfg, 'BB_RECOVERY_EXIT_TOLERANCE_ATR_MULT_TRADIER', 0))
    _def = float(_DEFAULTS_625.get('BB_RECOVERY_EXIT_TOLERANCE_ATR_MULT_TRADIER', 0) or 0)
    if abs(_thr - _def) > 1e-9:
        _v = _safe(npz, 'bb_pct_b_1h', n, 0.5)
        _thr2 = 0.5 + ((_thr % 1.0)-0.5)*0.2
        out = out | (_v > _thr2 if is_long else _v < _thr2)
    # BB_RECOVERY_EXIT_TOLERANCE_PCT_TRADIER (num) -> mfi_1h
    _thr = float(getattr(cfg, 'BB_RECOVERY_EXIT_TOLERANCE_PCT_TRADIER', 0))
    _def = float(_DEFAULTS_625.get('BB_RECOVERY_EXIT_TOLERANCE_PCT_TRADIER', 0) or 0)
    if abs(_thr - _def) > 1e-9:
        _v = _safe(npz, 'mfi_1h', n, 50)
        _bound = 50 + (_thr % 20) -10
        out = out | (_v > _bound if is_long else _v < _bound)
